/* =========================================================   RECEITAS (Vendas) - TIPMOV = 'V'========================================================= */SELECT    CONCAT('N_', C.CODNAT) AS ID,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '01' THEN ABS(ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) ELSE 0 END) AS JAN,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '02' THEN ABS(ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) ELSE 0 END) AS FEV,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '03' THEN ABS(ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) ELSE 0 END) AS MAR,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '04' THEN ABS(ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) ELSE 0 END) AS ABR,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '05' THEN ABS(ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) ELSE 0 END) AS MAI,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '06' THEN ABS(ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) ELSE 0 END) AS JUN,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '07' THEN ABS(ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) ELSE 0 END) AS JUL,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '08' THEN ABS(ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) ELSE 0 END) AS AGO,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '09' THEN ABS(ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) ELSE 0 END) AS SETEMBRO,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '10' THEN ABS(ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) ELSE 0 END) AS OUTUBRO,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '11' THEN ABS(ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) ELSE 0 END) AS NOV,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '12' THEN ABS(ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) ELSE 0 END) AS DEZ,    SUM(ABS(ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST)) AS TOTAL_ANOFROM IMP_IMP_CAB C JOIN IMP_NATUREZA N ON N.CODNAT = C.CODNAT JOIN IMP_IMP_TOP T ON C.CODTIPOPER = T.CODTIPOPER AND C.DHTIPOPER = T.DHALTER JOIN IMP_IMP_ITE ITE ON C.NUNOTA = ITE.NUNOTA WHERE (:VAR_DATA_INICIO IS NULL OR :VAR_DATA_INICIO = '' OR C.DTNEG >= :VAR_DATA_INICIO)   AND (:VAR_DATA_FIM IS NULL OR :VAR_DATA_FIM = '' OR C.DTNEG <= :VAR_DATA_FIM)   AND T.GOLSINAL = -1   AND C.TIPMOV = 'V'   AND C.STATUSNOTA = 'L'   AND (:VAR_NATUREZA IS NULL OR :VAR_NATUREZA = '' OR FIND_IN_SET(C.CODNAT, :VAR_NATUREZA))   AND (:VAR_CENTRO_RESULTADO IS NULL OR :VAR_CENTRO_RESULTADO = '' OR FIND_IN_SET(C.CODCENCUS, :VAR_CENTRO_RESULTADO)) GROUP BY N.CODNATUNION ALL/* =========================================================   DEVOLUÇÕES========================================================= */SELECT    CONCAT('N_', C.CODNAT) AS ID,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '01' THEN ABS((ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) * -1) ELSE 0 END) AS JAN,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '02' THEN ABS((ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) * -1) ELSE 0 END) AS FEV,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '03' THEN ABS((ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) * -1) ELSE 0 END) AS MAR,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '04' THEN ABS((ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) * -1) ELSE 0 END) AS ABR,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '05' THEN ABS((ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) * -1) ELSE 0 END) AS MAI,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '06' THEN ABS((ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) * -1) ELSE 0 END) AS JUN,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '07' THEN ABS((ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) * -1) ELSE 0 END) AS JUL,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '08' THEN ABS((ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) * -1) ELSE 0 END) AS AGO,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '09' THEN ABS((ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) * -1) ELSE 0 END) AS SETEMBRO,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '10' THEN ABS((ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) * -1) ELSE 0 END) AS OUTUBRO,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '11' THEN ABS((ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) * -1) ELSE 0 END) AS NOV,    SUM(CASE WHEN DATE_FORMAT(C.DTNEG, '%m') = '12' THEN ABS((ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) * -1) ELSE 0 END) AS DEZ,    SUM(ABS((ITE.VLRTOT - ITE.VLRDESC + ITE.VLRIPI + ITE.VLRSUBST) * -1)) AS TOTAL_ANOFROM IMP_IMP_CAB C JOIN IMP_NATUREZA N ON C.CODNAT = N.CODNAT JOIN IMP_IMP_TOP T ON C.CODTIPOPER = T.CODTIPOPER AND C.DHTIPOPER = T.DHALTER JOIN IMP_IMP_ITE ITE ON C.NUNOTA = ITE.NUNOTA WHERE (:VAR_DATA_INICIO IS NULL OR :VAR_DATA_INICIO = '' OR C.DTNEG >= :VAR_DATA_INICIO)   AND (:VAR_DATA_FIM IS NULL OR :VAR_DATA_FIM = '' OR C.DTNEG <= :VAR_DATA_FIM)   AND T.GOLDEV = -1   AND C.TIPMOV = 'D'   AND C.STATUSNOTA = 'L'   AND C.CODNAT NOT IN (1101001, 1103005, 1103006)   AND (:VAR_NATUREZA IS NULL OR :VAR_NATUREZA = '' OR FIND_IN_SET(C.CODNAT, :VAR_NATUREZA))   AND (:VAR_CENTRO_RESULTADO IS NULL OR :VAR_CENTRO_RESULTADO = '' OR FIND_IN_SET(C.CODCENCUS, :VAR_CENTRO_RESULTADO)) GROUP BY N.CODNATUNION ALL/* =========================================================   FINANCEIRO (CORRIGIDO PARA NETTING)========================================================= */SELECT    CONCAT('N_', F.CODNAT) AS ID,    ABS(SUM(CASE WHEN DATE_FORMAT(F.DTNEG, '%m') = '01' THEN (F.VALOR * F.RECDESP) ELSE 0 END)) AS JAN,    ABS(SUM(CASE WHEN DATE_FORMAT(F.DTNEG, '%m') = '02' THEN (F.VALOR * F.RECDESP) ELSE 0 END)) AS FEV,    ABS(SUM(CASE WHEN DATE_FORMAT(F.DTNEG, '%m') = '03' THEN (F.VALOR * F.RECDESP) ELSE 0 END)) AS MAR,    ABS(SUM(CASE WHEN DATE_FORMAT(F.DTNEG, '%m') = '04' THEN (F.VALOR * F.RECDESP) ELSE 0 END)) AS ABR,    ABS(SUM(CASE WHEN DATE_FORMAT(F.DTNEG, '%m') = '05' THEN (F.VALOR * F.RECDESP) ELSE 0 END)) AS MAI,    ABS(SUM(CASE WHEN DATE_FORMAT(F.DTNEG, '%m') = '06' THEN (F.VALOR * F.RECDESP) ELSE 0 END)) AS JUN,    ABS(SUM(CASE WHEN DATE_FORMAT(F.DTNEG, '%m') = '07' THEN (F.VALOR * F.RECDESP) ELSE 0 END)) AS JUL,    ABS(SUM(CASE WHEN DATE_FORMAT(F.DTNEG, '%m') = '08' THEN (F.VALOR * F.RECDESP) ELSE 0 END)) AS AGO,    ABS(SUM(CASE WHEN DATE_FORMAT(F.DTNEG, '%m') = '09' THEN (F.VALOR * F.RECDESP) ELSE 0 END)) AS SETEMBRO,    ABS(SUM(CASE WHEN DATE_FORMAT(F.DTNEG, '%m') = '10' THEN (F.VALOR * F.RECDESP) ELSE 0 END)) AS OUTUBRO,    ABS(SUM(CASE WHEN DATE_FORMAT(F.DTNEG, '%m') = '11' THEN (F.VALOR * F.RECDESP) ELSE 0 END)) AS NOV,    ABS(SUM(CASE WHEN DATE_FORMAT(F.DTNEG, '%m') = '12' THEN (F.VALOR * F.RECDESP) ELSE 0 END)) AS DEZ,    ABS(SUM(F.VALOR * F.RECDESP)) AS TOTAL_ANOFROM IMP_FINANCEIRO_DRE FWHERE (:VAR_DATA_INICIO IS NULL OR :VAR_DATA_INICIO = '' OR F.DTNEG >= :VAR_DATA_INICIO)  AND (:VAR_DATA_FIM IS NULL OR :VAR_DATA_FIM = '' OR F.DTNEG <= :VAR_DATA_FIM)  AND (F.RECDESP = -1 OR (F.RECDESP = 1 AND F.NUNOTA IS NULL))  AND F.CODNAT NOT IN (1101001, 1103005, 1103006, 1102001, 1102002)  AND (:VAR_NATUREZA IS NULL OR :VAR_NATUREZA = '' OR FIND_IN_SET(F.CODNAT, :VAR_NATUREZA))  AND (:VAR_CENTRO_RESULTADO IS NULL OR :VAR_CENTRO_RESULTADO = '' OR FIND_IN_SET(F.CODCENCUS, :VAR_CENTRO_RESULTADO))GROUP BY F.CODNATUNION ALL/* =========================================================   CMV========================================================= */SELECT    CONCAT('N_', 99998) AS ID,    SUM(CASE WHEN DATE_FORMAT(MES_REF, '%m') = '01' THEN ABS(CMV) ELSE 0 END) AS JAN,    SUM(CASE WHEN DATE_FORMAT(MES_REF, '%m') = '02' THEN ABS(CMV) ELSE 0 END) AS FEV,    SUM(CASE WHEN DATE_FORMAT(MES_REF, '%m') = '03' THEN ABS(CMV) ELSE 0 END) AS MAR,    SUM(CASE WHEN DATE_FORMAT(MES_REF, '%m') = '04' THEN ABS(CMV) ELSE 0 END) AS ABR,    SUM(CASE WHEN DATE_FORMAT(MES_REF, '%m') = '05' THEN ABS(CMV) ELSE 0 END) AS MAI,    SUM(CASE WHEN DATE_FORMAT(MES_REF, '%m') = '06' THEN ABS(CMV) ELSE 0 END) AS JUN,    SUM(CASE WHEN DATE_FORMAT(MES_REF, '%m') = '07' THEN ABS(CMV) ELSE 0 END) AS JUL,    SUM(CASE WHEN DATE_FORMAT(MES_REF, '%m') = '08' THEN ABS(CMV) ELSE 0 END) AS AGO,    SUM(CASE WHEN DATE_FORMAT(MES_REF, '%m') = '09' THEN ABS(CMV) ELSE 0 END) AS SETEMBRO,    SUM(CASE WHEN DATE_FORMAT(MES_REF, '%m') = '10' THEN ABS(CMV) ELSE 0 END) AS OUTUBRO,    SUM(CASE WHEN DATE_FORMAT(MES_REF, '%m') = '11' THEN ABS(CMV) ELSE 0 END) AS NOV,    SUM(CASE WHEN DATE_FORMAT(MES_REF, '%m') = '12' THEN ABS(CMV) ELSE 0 END) AS DEZ,    SUM(ABS(CMV)) AS TOTAL_ANOFROM IMP_CMV WHERE (:VAR_DATA_INICIO IS NULL OR :VAR_DATA_INICIO = '' OR MES_REF >= :VAR_DATA_INICIO)   AND (:VAR_DATA_FIM IS NULL OR :VAR_DATA_FIM = '' OR MES_REF <= :VAR_DATA_FIM)UNION ALL/* =========================================================   DEPRECIAÇÃO========================================================= */SELECT    CONCAT('N_', 99996) AS ID,    SUM(CASE WHEN SUBSTR(PERIODO, 4, 2) = '01' THEN VALOR ELSE 0 END) AS JAN,    SUM(CASE WHEN SUBSTR(PERIODO, 4, 2) = '02' THEN VALOR ELSE 0 END) AS FEV,    SUM(CASE WHEN SUBSTR(PERIODO, 4, 2) = '03' THEN VALOR ELSE 0 END) AS MAR,    SUM(CASE WHEN SUBSTR(PERIODO, 4, 2) = '04' THEN VALOR ELSE 0 END) AS ABR,    SUM(CASE WHEN SUBSTR(PERIODO, 4, 2) = '05' THEN VALOR ELSE 0 END) AS MAI,    SUM(CASE WHEN SUBSTR(PERIODO, 4, 2) = '06' THEN VALOR ELSE 0 END) AS JUN,    SUM(CASE WHEN SUBSTR(PERIODO, 4, 2) = '07' THEN VALOR ELSE 0 END) AS JUL,    SUM(CASE WHEN SUBSTR(PERIODO, 4, 2) = '08' THEN VALOR ELSE 0 END) AS AGO,    SUM(CASE WHEN SUBSTR(PERIODO, 4, 2) = '09' THEN VALOR ELSE 0 END) AS SETEMBRO,    SUM(CASE WHEN SUBSTR(PERIODO, 4, 2) = '10' THEN VALOR ELSE 0 END) AS OUTUBRO,    SUM(CASE WHEN SUBSTR(PERIODO, 4, 2) = '11' THEN VALOR ELSE 0 END) AS NOV,    SUM(CASE WHEN SUBSTR(PERIODO, 4, 2) = '12' THEN VALOR ELSE 0 END) AS DEZ,    SUM(VALOR) AS TOTAL_ANOFROM DEPRECIACAO WHERE (:VAR_DATA_INICIO IS NULL OR :VAR_DATA_INICIO = '' OR STR_TO_DATE(PERIODO, '%d/%m/%Y') >= :VAR_DATA_INICIO)   AND (:VAR_DATA_FIM IS NULL OR :VAR_DATA_FIM = '' OR STR_TO_DATE(PERIODO, '%d/%m/%Y') <= :VAR_DATA_FIM)UNION ALL/* =========================================================   VARIAÇÃO CAMBIAL========================================================= */SELECT    CASE        WHEN VC.TIPVAR = 'P' THEN CONCAT('N_', 99994)        WHEN VC.TIPVAR = 'N' THEN CONCAT('N_', 99995)    END AS ID,    SUM(CASE WHEN DATE_FORMAT(VC.DTREF, '%m') = '01' THEN VC.VALOR ELSE 0 END) AS JAN,    SUM(CASE WHEN DATE_FORMAT(VC.DTREF, '%m') = '02' THEN VC.VALOR ELSE 0 END) AS FEV,    SUM(CASE WHEN DATE_FORMAT(VC.DTREF, '%m') = '03' THEN VC.VALOR ELSE 0 END) AS MAR,    SUM(CASE WHEN DATE_FORMAT(VC.DTREF, '%m') = '04' THEN VC.VALOR ELSE 0 END) AS ABR,    SUM(CASE WHEN DATE_FORMAT(VC.DTREF, '%m') = '05' THEN VC.VALOR ELSE 0 END) AS MAI,    SUM(CASE WHEN DATE_FORMAT(VC.DTREF, '%m') = '06' THEN VC.VALOR ELSE 0 END) AS JUN,    SUM(CASE WHEN DATE_FORMAT(VC.DTREF, '%m') = '07' THEN VC.VALOR ELSE 0 END) AS JUL,    SUM(CASE WHEN DATE_FORMAT(VC.DTREF, '%m') = '08' THEN VC.VALOR ELSE 0 END) AS AGO,    SUM(CASE WHEN DATE_FORMAT(VC.DTREF, '%m') = '09' THEN VC.VALOR ELSE 0 END) AS SETEMBRO,    SUM(CASE WHEN DATE_FORMAT(VC.DTREF, '%m') = '10' THEN VC.VALOR ELSE 0 END) AS OUTUBRO,    SUM(CASE WHEN DATE_FORMAT(VC.DTREF, '%m') = '11' THEN VC.VALOR ELSE 0 END) AS NOV,    SUM(CASE WHEN DATE_FORMAT(VC.DTREF, '%m') = '12' THEN VC.VALOR ELSE 0 END) AS DEZ,    SUM(VC.VALOR) AS TOTAL_ANOFROM IMP_VARIACAO_CAMB VC WHERE (:VAR_DATA_INICIO IS NULL OR :VAR_DATA_INICIO = '' OR VC.DTREF >= :VAR_DATA_INICIO)   AND (:VAR_DATA_FIM IS NULL OR :VAR_DATA_FIM = '' OR VC.DTREF <= :VAR_DATA_FIM)   AND (:VAR_NATUREZA IS NULL OR :VAR_NATUREZA = '' OR FIND_IN_SET(VC.CODNAT, :VAR_NATUREZA))   AND (:VAR_CENTRO_RESULTADO IS NULL OR :VAR_CENTRO_RESULTADO = '' OR FIND_IN_SET(VC.CODCENCUS, :VAR_CENTRO_RESULTADO)) GROUP BY IDUNION ALL/* =========================================================   DESCONTOS OBTIDOS E CONCEDIDOS========================================================= */SELECT    CASE        WHEN D.RECDESP = -1 THEN CONCAT('N_', 99993)        WHEN D.RECDESP = 1 THEN CONCAT('N_', 99992)    END AS ID,    SUM(CASE WHEN DATE_FORMAT(D.DTREF, '%m') = '01' THEN D.VALOR ELSE 0 END) AS JAN,    SUM(CASE WHEN DATE_FORMAT(D.DTREF, '%m') = '02' THEN D.VALOR ELSE 0 END) AS FEV,    SUM(CASE WHEN DATE_FORMAT(D.DTREF, '%m') = '03' THEN D.VALOR ELSE 0 END) AS MAR,    SUM(CASE WHEN DATE_FORMAT(D.DTREF, '%m') = '04' THEN D.VALOR ELSE 0 END) AS ABR,    SUM(CASE WHEN DATE_FORMAT(D.DTREF, '%m') = '05' THEN D.VALOR ELSE 0 END) AS MAI,    SUM(CASE WHEN DATE_FORMAT(D.DTREF, '%m') = '06' THEN D.VALOR ELSE 0 END) AS JUN,    SUM(CASE WHEN DATE_FORMAT(D.DTREF, '%m') = '07' THEN D.VALOR ELSE 0 END) AS JUL,    SUM(CASE WHEN DATE_FORMAT(D.DTREF, '%m') = '08' THEN D.VALOR ELSE 0 END) AS AGO,    SUM(CASE WHEN DATE_FORMAT(D.DTREF, '%m') = '09' THEN D.VALOR ELSE 0 END) AS SETEMBRO,    SUM(CASE WHEN DATE_FORMAT(D.DTREF, '%m') = '10' THEN D.VALOR ELSE 0 END) AS OUTUBRO,    SUM(CASE WHEN DATE_FORMAT(D.DTREF, '%m') = '11' THEN D.VALOR ELSE 0 END) AS NOV,    SUM(CASE WHEN DATE_FORMAT(D.DTREF, '%m') = '12' THEN D.VALOR ELSE 0 END) AS DEZ,    SUM(D.VALOR) AS TOTAL_ANOFROM IMP_DESCONTOS_CONC D WHERE (:VAR_DATA_INICIO IS NULL OR :VAR_DATA_INICIO = '' OR D.DTREF >= :VAR_DATA_INICIO)   AND (:VAR_DATA_FIM IS NULL OR :VAR_DATA_FIM = '' OR D.DTREF <= :VAR_DATA_FIM)   AND (:VAR_NATUREZA IS NULL OR :VAR_NATUREZA = '' OR FIND_IN_SET(D.CODNAT, :VAR_NATUREZA))   AND (:VAR_CENTRO_RESULTADO IS NULL OR :VAR_CENTRO_RESULTADO = '' OR FIND_IN_SET(D.CODCENCUS, :VAR_CENTRO_RESULTADO)) GROUP BY IDUNION ALL/* =========================================================   JUROS E MULTAS========================================================= */SELECT    ID,    SUM(JAN) AS JAN,    SUM(FEV) AS FEV,    SUM(MAR) AS MAR,    SUM(ABR) AS ABR,    SUM(MAI) AS MAI,    SUM(JUN) AS JUN,    SUM(JUL) AS JUL,    SUM(AGO) AS AGO,    SUM(SETEMBRO) AS SETEMBRO,    SUM(OUTUBRO) AS OUTUBRO,    SUM(NOV) AS NOV,    SUM(DEZ) AS DEZ,    SUM(TOTAL_ANO) AS TOTAL_ANOFROM (    SELECT        CASE WHEN JM.RECDESP = 1 THEN CONCAT('N_', 99991)             WHEN JM.RECDESP = -1 THEN CONCAT('N_', 99989)        END AS ID,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '01' THEN JM.JUROS ELSE 0 END) AS JAN,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '02' THEN JM.JUROS ELSE 0 END) AS FEV,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '03' THEN JM.JUROS ELSE 0 END) AS MAR,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '04' THEN JM.JUROS ELSE 0 END) AS ABR,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '05' THEN JM.JUROS ELSE 0 END) AS MAI,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '06' THEN JM.JUROS ELSE 0 END) AS JUN,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '07' THEN JM.JUROS ELSE 0 END) AS JUL,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '08' THEN JM.JUROS ELSE 0 END) AS AGO,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '09' THEN JM.JUROS ELSE 0 END) AS SETEMBRO,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '10' THEN JM.JUROS ELSE 0 END) AS OUTUBRO,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '11' THEN JM.JUROS ELSE 0 END) AS NOV,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '12' THEN JM.JUROS ELSE 0 END) AS DEZ,        SUM(JM.JUROS) AS TOTAL_ANO    FROM IMP_JUROS_MULTAS JM    WHERE JM.JUROS > 0      AND (:VAR_DATA_INICIO IS NULL OR :VAR_DATA_INICIO = '' OR JM.DTREF >= :VAR_DATA_INICIO)      AND (:VAR_DATA_FIM IS NULL OR :VAR_DATA_FIM = '' OR JM.DTREF <= :VAR_DATA_FIM)      AND (:VAR_NATUREZA IS NULL OR :VAR_NATUREZA = '' OR FIND_IN_SET(JM.CODNAT, :VAR_NATUREZA))      AND (:VAR_CENTRO_RESULTADO IS NULL OR :VAR_CENTRO_RESULTADO = '' OR FIND_IN_SET(JM.CODCENCUS, :VAR_CENTRO_RESULTADO))    GROUP BY ID    UNION ALL    SELECT        CASE WHEN JM.RECDESP = 1 THEN CONCAT('N_', 99990)             WHEN JM.RECDESP = -1 THEN CONCAT('N_', 99988)        END AS ID,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '01' THEN JM.MULTA ELSE 0 END) AS JAN,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '02' THEN JM.MULTA ELSE 0 END) AS FEV,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '03' THEN JM.MULTA ELSE 0 END) AS MAR,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '04' THEN JM.MULTA ELSE 0 END) AS ABR,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '05' THEN JM.MULTA ELSE 0 END) AS MAI,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '06' THEN JM.MULTA ELSE 0 END) AS JUN,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '07' THEN JM.MULTA ELSE 0 END) AS JUL,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '08' THEN JM.MULTA ELSE 0 END) AS AGO,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '09' THEN JM.MULTA ELSE 0 END) AS SETEMBRO,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '10' THEN JM.MULTA ELSE 0 END) AS OUTUBRO,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '11' THEN JM.MULTA ELSE 0 END) AS NOV,        SUM(CASE WHEN DATE_FORMAT(JM.DTREF, '%m') = '12' THEN JM.MULTA ELSE 0 END) AS DEZ,        SUM(JM.MULTA) AS TOTAL_ANO    FROM IMP_JUROS_MULTAS JM    WHERE JM.MULTA > 0      AND (:VAR_DATA_INICIO IS NULL OR :VAR_DATA_INICIO = '' OR JM.DTREF >= :VAR_DATA_INICIO)      AND (:VAR_DATA_FIM IS NULL OR :VAR_DATA_FIM = '' OR JM.DTREF <= :VAR_DATA_FIM)      AND (:VAR_NATUREZA IS NULL OR :VAR_NATUREZA = '' OR FIND_IN_SET(JM.CODNAT, :VAR_NATUREZA))      AND (:VAR_CENTRO_RESULTADO IS NULL OR :VAR_CENTRO_RESULTADO = '' OR FIND_IN_SET(JM.CODCENCUS, :VAR_CENTRO_RESULTADO))    GROUP BY ID) AS JurosMultas GROUP BY IDUNION ALL/* =========================================================   IMPOSTOS (IMP_IMPOSTOS)========================================================= */SELECT    CONCAT('IMP_', I.CODIMP) AS ID,    SUM(CASE WHEN DATE_FORMAT(I.DTREF, '%m') = '01' THEN ABS(I.VLR) ELSE 0 END) AS JAN,    SUM(CASE WHEN DATE_FORMAT(I.DTREF, '%m') = '02' THEN ABS(I.VLR) ELSE 0 END) AS FEV,    SUM(CASE WHEN DATE_FORMAT(I.DTREF, '%m') = '03' THEN ABS(I.VLR) ELSE 0 END) AS MAR,    SUM(CASE WHEN DATE_FORMAT(I.DTREF, '%m') = '04' THEN ABS(I.VLR) ELSE 0 END) AS ABR,    SUM(CASE WHEN DATE_FORMAT(I.DTREF, '%m') = '05' THEN ABS(I.VLR) ELSE 0 END) AS MAI,    SUM(CASE WHEN DATE_FORMAT(I.DTREF, '%m') = '06' THEN ABS(I.VLR) ELSE 0 END) AS JUN,    SUM(CASE WHEN DATE_FORMAT(I.DTREF, '%m') = '07' THEN ABS(I.VLR) ELSE 0 END) AS JUL,    SUM(CASE WHEN DATE_FORMAT(I.DTREF, '%m') = '08' THEN ABS(I.VLR) ELSE 0 END) AS AGO,    SUM(CASE WHEN DATE_FORMAT(I.DTREF, '%m') = '09' THEN ABS(I.VLR) ELSE 0 END) AS SETEMBRO,    SUM(CASE WHEN DATE_FORMAT(I.DTREF, '%m') = '10' THEN ABS(I.VLR) ELSE 0 END) AS OUTUBRO,    SUM(CASE WHEN DATE_FORMAT(I.DTREF, '%m') = '11' THEN ABS(I.VLR) ELSE 0 END) AS NOV,    SUM(CASE WHEN DATE_FORMAT(I.DTREF, '%m') = '12' THEN ABS(I.VLR) ELSE 0 END) AS DEZ,    SUM(ABS(I.VLR)) AS TOTAL_ANOFROM IMP_IMPOSTOS I WHERE (:VAR_DATA_INICIO IS NULL OR :VAR_DATA_INICIO = '' OR I.DTREF >= :VAR_DATA_INICIO)   AND (:VAR_DATA_FIM IS NULL OR :VAR_DATA_FIM = '' OR I.DTREF <= :VAR_DATA_FIM)   AND (:VAR_NATUREZA IS NULL OR :VAR_NATUREZA = '' OR FIND_IN_SET(I.CODNAT, :VAR_NATUREZA))   AND (:VAR_CENTRO_RESULTADO IS NULL OR :VAR_CENTRO_RESULTADO = '' OR FIND_IN_SET(I.CODCENCUS, :VAR_CENTRO_RESULTADO)) GROUP BY I.CODIMPUNION ALL/* =========================================================   CRÉDITO PRESUMIDO========================================================= */SELECT    'N_CREDITO_PRESUMIDO' AS ID,    SUM(CASE WHEN DATE_FORMAT(C.DTREF, '%m') = '01' THEN C.CREDITO ELSE 0 END) AS JAN,    SUM(CASE WHEN DATE_FORMAT(C.DTREF, '%m') = '02' THEN C.CREDITO ELSE 0 END) AS FEV,    SUM(CASE WHEN DATE_FORMAT(C.DTREF, '%m') = '03' THEN C.CREDITO ELSE 0 END) AS MAR,    SUM(CASE WHEN DATE_FORMAT(C.DTREF, '%m') = '04' THEN C.CREDITO ELSE 0 END) AS ABR,    SUM(CASE WHEN DATE_FORMAT(C.DTREF, '%m') = '05' THEN C.CREDITO ELSE 0 END) AS MAI,    SUM(CASE WHEN DATE_FORMAT(C.DTREF, '%m') = '06' THEN C.CREDITO ELSE 0 END) AS JUN,    SUM(CASE WHEN DATE_FORMAT(C.DTREF, '%m') = '07' THEN C.CREDITO ELSE 0 END) AS JUL,    SUM(CASE WHEN DATE_FORMAT(C.DTREF, '%m') = '08' THEN C.CREDITO ELSE 0 END) AS AGO,    SUM(CASE WHEN DATE_FORMAT(C.DTREF, '%m') = '09' THEN C.CREDITO ELSE 0 END) AS SETEMBRO,    SUM(CASE WHEN DATE_FORMAT(C.DTREF, '%m') = '10' THEN C.CREDITO ELSE 0 END) AS OUTUBRO,    SUM(CASE WHEN DATE_FORMAT(C.DTREF, '%m') = '11' THEN C.CREDITO ELSE 0 END) AS NOV,    SUM(CASE WHEN DATE_FORMAT(C.DTREF, '%m') = '12' THEN C.CREDITO ELSE 0 END) AS DEZ,    SUM(C.CREDITO) AS TOTAL_ANOFROM IMP_CREDITO C WHERE (:VAR_DATA_INICIO IS NULL OR :VAR_DATA_INICIO = '' OR C.DTREF >= :VAR_DATA_INICIO)   AND (:VAR_DATA_FIM IS NULL OR :VAR_DATA_FIM = '' OR C.DTREF <= :VAR_DATA_FIM)   AND (:VAR_NATUREZA IS NULL OR :VAR_NATUREZA = '' OR FIND_IN_SET(C.CODNAT, :VAR_NATUREZA))   AND (:VAR_CENTRO_RESULTADO IS NULL OR :VAR_CENTRO_RESULTADO = '' OR FIND_IN_SET(C.CODCENCUS, :VAR_CENTRO_RESULTADO)) GROUP BY ID;